var n=`1191-pepian`;var t=`world-1191`;var s=`GT`;var a=`central-america-caribbean`;var o=4;var r=93;var d={en:`Pepián`,ua:`Пепіан`};var g={en:`Pepián is a dish from Guatemala prepared with pumpkin seeds, white sesame seeds, dried guajillo chilies, tomato. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Пепіан, страва кухні країни Гватемала, яку готують із таких продуктів: гарбузове насіння, білий кунжут, сушений перець гуахільйо, помідор. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var l=[{en:`Toast these ingredients over medium heat for about 6 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 6 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:6,i:[[`pumpkin-seeds`,150,`g`],[`white-sesame-seeds`,55,`g`],[`dried-guajillo-chilies`,3,`pcs`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`tomato`,330,`g`],[`yellow-onion`,180,`g`],[`garlic`,5,`clove`],[`canola-oil`,35,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:9,i:[[`ground-cinnamon`,4,`g`],[`ground-black-pepper`,4,`g`],[`water`,200,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 65 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 65 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:65,i:[[`chicken-thigh`,850,`g`],[`chicken-stock`,750,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`]]}];var m={slug:n,id:t,country:`GT`,region:a,servings:4,minutes:93,title:d,text:g,steps:l};export{s as country,m as default,t as id,r as minutes,a as region,o as servings,n as slug,l as steps,g as text,d as title};